import sys, ezdxf
for p in sys.argv[1:]:
    print("=====", p[-14:])
    d = ezdxf.readfile(p)
    for e in d.modelspace():
        t = e.dxftype()
        if t == "LINE":
            print("L", e.dxf.layer, round(e.dxf.start.x,2), round(e.dxf.start.y,2), round(e.dxf.end.x,2), round(e.dxf.end.y,2))
        elif t == "ARC":
            print("A", e.dxf.layer, round(e.dxf.center.x,2), round(e.dxf.center.y,2), "R", round(e.dxf.radius,2), round(e.dxf.start_angle,1), round(e.dxf.end_angle,1))
        elif t == "CIRCLE":
            print("C", e.dxf.layer, round(e.dxf.center.x,2), round(e.dxf.center.y,2), "R", round(e.dxf.radius,2))
        else:
            print(t, e.dxf.layer)

